function templateCards() {
  const parent = mapPageText(getOperation('quickModel'));
  return parent.templates.map(template => {
    const kind = template.kind, model = QUICK_MODELS[kind];
    const schema = parent.inputSchema.oneOf.find(item => item.properties.kind.const === kind);
    if (!schema || !model) throw new Error(`Missing registered template contract: ${kind}`);
    const { templates, defaults, inputSchema, minimalExample, normalExample, schemaHash, ...shared } = parent;
    return { ...shared, id:`template.${kind}`, category:'template', operationId:'quickModel',
      title:model.label, label:model.label,
      synonyms:[kind,model.label,model.labelEn].filter(Boolean),
      description:model.description || template.description,
      inputSchema:schema, schemaHash:contractHash(schema), defaults:template.defaults, fields:template.fields,placementPolicy:{...placementContract('quickModel'),defaultInsertionAnchor:model.defaultInsertionAnchor||'model-origin'},
      runtimeAvailability:'requires_ready_page',
      usage:'Discovery card only. Use run method:add with op:quickModel and params.kind from minimalExample. Do not pass template IDs or this subset schemaHash to execute. run reads the parent operation version/hash.',
      minimalExample:{op:'quickModel',params:template.minimalExample,refs:[]},
      normalExample:{op:'quickModel',params:template.normalExample,refs:[]},
      knownUnsupportedCases:template.knownUnsupportedCases,
      relatedTools:['quickModel','measure','feature.edit'], docs:'api.workflow' };
  });
}
let cachedCards;
function pageCards() {
  return cachedCards ??= [
    ...listOperations().filter(card => !['import', 'remove'].includes(card.id)).map(raw => {
      const card = mapPageText(raw);
      return { ...card,
      title: pageWording(card.title), label: TOOL_LABELS[card.id] || card.title,
      synonyms: [...new Set([...(card.synonyms || []), ...(TOOL_LABELS[card.id] || '').split(/\s*\/\s*/)].filter(Boolean))],
      description: pageWording(card.description),
      coordinateConvention: pageWording(card.coordinateConvention),
      placementPolicy:placementContract(card.id),
      relatedTools: ['getState', 'getTool', 'queryGeometry', 'execute'],
      apiCompatibility: card.strictContract ? ['page-v2'] : ['page-advisory'],
      runtimeAvailability: 'requires_ready_page',
      usage: 'Prefer run steps with method:add and args:{op,params,refs,name?,placement?}; run fills version/schemaHash from this catalog. ' + (['C','T'].includes(PLACEMENT_POLICIES[card.id])||['faceHole','logo','transform','copy','mirror','linearPattern','circularPattern','split','planeSection','referenceExtrude'].includes(card.id)?'Explicit placement version 1 is enabled; read api.references. ':'Placement is not enabled for this operation. ') + (card.strictContract ? 'Strict v2 validation applies.' : 'Schema is advisory; kernel prerequisites and result verification still apply.'),
      idempotency: 'Current documentInstanceId in-memory receipts only; no cross-reload guarantee.',
      minimalExample: { ...card.minimalExample,
        referenceInstructions: 'Resolve body IDs from getState(). Topology indices are snapshot-local; use queryGeometry().' },
      normalExample: { ...card.normalExample,
        referenceInstructions: 'Resolve body IDs from getState(). Topology indices are snapshot-local; use queryGeometry().' },
      invalidExamples: card.strictContract ? card.invalidExamples : [],
      knownUnsupportedCases: card.knownUnsupportedCases.filter(item => !/MCP|legacy entry|M2/.test(item)) }; }),
    ...templateCards(), ...PAGE_METHODS.map(methodCard), ...Object.keys(commandSpecs).map(commandCard), namedParameterCard(), ...FILE_METHODS.map(fileCard),
    ...unavailable.map(card => ({ ...card, category: 'unavailable', version: PAGE_DOC_VERSION,
      implementationStatus: 'unavailable', contractStatus: 'unavailable', runtimeAvailability: 'unavailable',
      errorCodes: ['CAPABILITY_UNAVAILABLE'] })),
  ];
}
export const pageCatalogHash = contractHash({ searchVersion: SEARCH_VERSION, cards: pageCards(), uiRoutes:UI_API_ROUTES, fileLimits: FILE_LIMITS });
export const pageDocsHash = contractHash({ pageCatalogHash, pageDocs: PAGE_DOCS, legacyReadable: [...LEGACY_READABLE], legacyDocsHash });
const cardsById = new Map(pageCards().map(card => [card.id, { ...card, docsHash: contractHash(card) }]));
const toolIndex = createToolIndex([...cardsById.values()]);

export function discoveryMetadata() {
  return { searchVersion: SEARCH_VERSION, pageApiVersion:PAGE_DOC_VERSION, apiVersion, entrypoint: 'window.webcad.api.connect',
    toolCount: cardsById.size, categories: [...new Set(pageCards().map(card => card.category))],
    catalogHash: pageCatalogHash, docsHash: pageDocsHash,
    quickstart: 'automation/quickstart.md', manifest: 'automation/manifest.json',
    snapshot: 'automation/index.json', offlineLibrary: 'automation/tool-library.mjs',
    protocol: { surface:'window.webcad.api', legacySurface:false, authority:'live page contracts',
      migration:'Old window.webcad.action/execute/ready and repository-generated manuals are not this page API. Reconnect and invalidate mismatched caches; do not guess compatibility.',
      skill:'automation/webcad-page-api/SKILL.md' },
    guidance: 'Use an authorized background page script channel; never auto-fallback to manual JSON UI. See api.connection for host capability discovery. Connect with includeContracts:true for short capability queries; batch getTools only for missing IDs. Read linked docs only as needed. Search hits are candidates, not plans. Cache contracts by docsHash, never document state or topology IDs.',
    execution: { units: { length: 'mm', angle: 'degrees', volume: 'mm^3' },
      maxSteps:20, atomic:false, contextField:'requestContext',
      operation: 'run({context:requestContext,idempotencyKey,steps:[{id,method:"add",args:{op,params,refs}}]})',
      command: 'run step {id,method:"execute",args:{action,args}}',
      reference: '{$ref:"previousStep.createdBodyIds.0"}; current body IDs come from this page.',
      receipt: 'Check status, per-step results and displayMatchesContext; atomic=false, stop on failure; unknown requires state inspection before replay.',
      template:'template.* cards are discovery views: run add op:quickModel with params.kind. Copy minimalExample, not the discovery ID.',
      workflow:'Read relevant cards once; compose named parts in bounded batches; measure key dimensions and setView; inspect receipts and the matching frame. Export only when requested.',
      docs: ['api.run','api.workflow','api.connection','api.discovery'] } };
}

export function infoMetadata({ buildId = 'unreported', browserReady = false } = {}) {
  return { product: 'WebCAD', buildId, apiVersion, pageApiVersion: PAGE_DOC_VERSION, transport: 'in-page',
    entrypoint: 'window.webcad.api', catalogHash: pageCatalogHash, docsHash: pageDocsHash, discovery: discoveryMetadata(),
    units: { length: 'mm', angle: 'degrees', volume: 'mm^3', scale: 'dimensionless' },
    ready: browserReady, modeling: browserReady ? 'available' : 'not_ready',
    methods: [...PAGE_METHODS], filesMethods: [...FILE_METHODS],
    examples:EXAMPLES,knowledge:{quickstart:'automation/quickstart.md',manifest:'automation/manifest.json',markdown:'automation/knowledge.md',json:'automation/index.json'},
    docs: [...new Set([...Object.keys(PAGE_DOCS), ...LEGACY_READABLE])].sort(),
    fileLimits: FILE_LIMITS,
    strictOperations: [...migratedOperationIds], otherOperations: 'advisory; actual page adapter and kernel result determine availability',
    unavailable: unavailable.map(({ id, description }) => ({ id, reason: description })),
    limitations: ['Page API visibility does not confirm ChatGPT sidebar script execution.',
      'No cross-reload idempotency or permanent topology IDs.', 'File/Blob objects may not cross a JSON-only host boundary.'] };
}

export function searchTools(input = {}, runtime = {}) {
  if (!input || Array.isArray(input) || typeof input !== 'object' || typeof input.query !== 'string' || input.query.length > 500)
    contractError('PARAM_SCHEMA_INVALID', 'input.query', 'Provide a query string of at most 500 characters.');
  const { query, category } = input, limit = input.limit ?? 10;
  const scope = contractHash({ pageCatalogHash, query, category: category || null }).slice(7);
  const cursorMatch = input.cursor === undefined ? null : new RegExp(`^${scope}:(\\d+)$`).exec(input.cursor);
  if (input.cursor !== undefined && !cursorMatch)
    contractError('PARAM_SCHEMA_INVALID', 'input.cursor', 'Cursor does not match this search and catalog.');
  const offset = cursorMatch ? Number(cursorMatch[1]) : 0;
  if (!Number.isInteger(limit) || limit < 1 || limit > 50 || !Number.isSafeInteger(offset) || offset < 0)
    contractError('PARAM_RANGE_INVALID', 'input', 'Invalid search limit or cursor.');
  if (category !== undefined && (typeof category !== 'string' || category.length > 100))
    contractError('PARAM_SCHEMA_INVALID', 'input.category', 'Provide a category string.');
  const matches = toolIndex.search(query, { category });
  if (offset > matches.length) contractError('PARAM_RANGE_INVALID', 'input.cursor', 'Cursor exceeds result count.');
  return { items: matches.slice(offset, offset + limit).map(hit => { const card = cardsById.get(hit.id); return ({ id: card.id, title: card.title,
    label: card.label || card.title, docsHash: card.docsHash, score: hit.score, matchedTerms: hit.matchedTerms,
    version: card.version, schemaHash: card.schemaHash || null, description: card.description.slice(0,240), descriptionTruncated:card.description.length>240,
    category: card.category, contractStatus: card.contractStatus, strictContract: card.strictContract === true,
    runtimeAvailability: card.runtimeAvailability === 'unavailable' ? 'unavailable'
      : runtime.browserReady === false ? 'not_ready' : runtime.browserReady === true ? 'available' : 'unknown' }); }),
    total: matches.length, nextCursor: offset + limit < matches.length ? `${scope}:${offset + limit}` : null, catalogHash: pageCatalogHash };
}

export function getTool(input) {
  if (!input || Array.isArray(input) || typeof input.id !== 'string')
    contractError('PARAM_SCHEMA_INVALID', 'input.id', 'Provide a registered tool ID.');
  const card = cardsById.get(input.id);
  if (!card) {
    if (['import', 'remove'].includes(input.id))
      contractError('CAPABILITY_UNAVAILABLE', 'input.id', 'Use the dedicated page file or execute action.', 'READ_TOOL_CONTRACT');
    getOperation(input.id); // Preserve the existing coded unknown-operation error.
    contractError('UNKNOWN_OPERATION', 'input.id', 'Tool is not registered in this page.');
  }
  if (input.version !== undefined && input.version !== card.version)
    contractError('OPERATION_VERSION_UNSUPPORTED', 'input.version', 'Requested version is not registered.', 'READ_TOOL_CONTRACT');
  return structuredClone(card);
}

export function getTools(input) {
  if (!input || Array.isArray(input) || Object.keys(input).some(key => !['ids','knownHashes','expectedCatalogHash'].includes(key)) ||
      !Array.isArray(input.ids) || input.ids.length < 1 || input.ids.length > 20 ||
      input.ids.some(id => typeof id !== 'string' || !id.length || id.length > 150) || new Set(input.ids).size !== input.ids.length)
    contractError('PARAM_SCHEMA_INVALID', 'input', 'Provide 1..20 unique tool IDs.');
  const known = input.knownHashes ?? {};
  if (!known || typeof known !== 'object' || Array.isArray(known) || Object.keys(known).length > 200 ||
      Object.values(known).some(hash => typeof hash !== 'string' || !/^sha256:[a-f0-9]{64}$/.test(hash)))
    contractError('PARAM_SCHEMA_INVALID', 'input.knownHashes', 'Provide a bounded map of complete cached card hashes.');
  if (input.expectedCatalogHash !== undefined && input.expectedCatalogHash !== pageCatalogHash)
    contractError('CATALOG_CHANGED', 'input.expectedCatalogHash', 'Reconnect and refresh the tool selection before using cached contracts.');
  return { catalogHash: pageCatalogHash, items: input.ids.map(id => {
    try {
      const card = getTool({ id });
      return { id, version: card.version, docsHash: card.docsHash,
        ...(Object.hasOwn(known,id) && known[id] === card.docsHash ? { status:'not_modified' } : { status:'read', card }) };
    } catch (error) { return { id, status:'error', error:{ code:error.code || 'UNKNOWN_OPERATION', message:error.message } }; }
  }) };
}

export function readDocs(input) {
  if (!input || Array.isArray(input) || typeof input.docId !== 'string')
    contractError('PARAM_SCHEMA_INVALID', 'input.docId', 'Provide a whitelisted documentation ID.');
  if (input.knownHash !== undefined && (typeof input.knownHash !== 'string' || !/^sha256:[a-f0-9]{64}$/.test(input.knownHash) || input.cursor !== undefined))
    contractError('PARAM_SCHEMA_INVALID', 'input.knownHash', 'Use a complete document hash without a pagination cursor.');
  const id = ALIASES[input.docId] || input.docId;
  const page = (body, actualVersion) => {
    if (input.version !== undefined && input.version !== actualVersion)
      contractError('OPERATION_VERSION_UNSUPPORTED', 'input.version', 'Requested documentation version is not registered.');
    const offset = input.cursor ? Number(input.cursor) : 0, limit = input.limitChars ?? 8000;
    if (!Number.isSafeInteger(offset) || offset < 0 || offset > body.length || !Number.isInteger(limit) || limit < 1000 || limit > 16000)
      contractError('PARAM_RANGE_INVALID', 'input', 'Invalid documentation cursor or limit.');
    const docsHash = contractHash({ id, body });
    if (input.knownHash === docsHash) return { docId:id, version:actualVersion, docsHash, status:'not_modified', nextCursor:null };
    return { docId: id, version: actualVersion, docsHash, status:'read',
      text: body.slice(offset, offset + limit), nextCursor: offset + limit < body.length ? String(offset + limit) : null };
  };
  if (Object.hasOwn(PAGE_DOCS, id)) {
    return page(PAGE_DOCS[id], PAGE_DOC_VERSION);
  }
  if (LEGACY_READABLE.has(id)) {
    const { knownHash, ...request } = input;
    const result = readLegacyDocs({ ...request, docId:id });
    if (knownHash === result.docsHash) return { docId:result.docId,version:result.version,docsHash:result.docsHash,status:'not_modified',nextCursor:null };
    return result;
  }
  const match = /^webcad:\/\/operations\/([^/]+)\/([^/]+)$/.exec(id);
  if (match) {
    const card = getTool({ id: match[1], version: match[2] });
    return page(JSON.stringify(card, null, 2), card.version);
  }
  contractError('PARAM_SCHEMA_INVALID', 'input.docId', 'Unknown documentation ID; paths are not accepted.');
}

export function createStaticPageApiIndex() {
  const metadata = infoMetadata();
  const lines = ['# WebCAD 页面 API 索引', '', `API ${metadata.pageApiVersion} · 操作目录 ${pageCatalogHash}`, '',
    '入口：`window.webcad.api.connect({queries:[能力关键词]})`，再批量 `getTools`。完整目录供按需查阅，页面 JS 执行取决于获授权的客户端能力。', '',
    '长度 mm、角度 degrees、体积 mm³。严格契约：' + migratedOperationIds.join('、') + '；其余操作为 advisory。', '',
    '## 页面方法', '', ...PAGE_METHODS.map(name => `- \`${name}\``), '', '## 文件方法', '',
    ...FILE_METHODS.map(name => `- \`files.${name}\``), '', '## 工具目录', ''];
  for (const card of pageCards()) lines.push(`- \`${card.id}\` · ${card.contractStatus} · ${card.description}`);
  return lines.join('\n') + '\n';
}
